        var parts = headFull.split('/');
        if (parts.length === 2 && parts[0] && parts[1] &&
            !(parts[0] === owner && parts[1] === repo)) {
            ho = parts[0];
            hr = parts[1];
        }
    }
    return _ghBranchExists(ho, hr, name);
}

